<script setup lang="ts">
import {computed,onMounted,ref,useId} from 'vue'
import StudentHomeworkList from './StudentHomeworkList.vue'
import ClassNotices from './ClassNotices.vue'
import {studentHomeworkGroups} from '../student-homework-groups'
import {scheduleApi} from '../schedules'
const today=ref(''),showHistory=ref(false),historyId=useId()
const loading=ref(false),error=ref(''),items=ref<any[]>([])
const groups=computed(()=>studentHomeworkGroups(items.value,today.value))
async function load(){loading.value=true;error.value='';try{const r=await scheduleApi('student/homework');items.value=r.homework;today.value=r.today}catch(e){error.value=e instanceof Error?e.message:'Unable to load homework.'}finally{loading.value=false}}
onMounted(load)
</script>
<template><ClassNotices /><section class="homework-panel"><div class="heading"><h2>Class homework</h2><div class="homework-actions"><button type="button" class="secondary" :aria-expanded="showHistory" :aria-controls="historyId" :disabled="loading" @click="showHistory=!showHistory">{{showHistory?'Hide history':'Homework history'}} ({{groups.history.length}})</button><button type="button" class="secondary" :disabled="loading" @click="load">Refresh</button></div></div><p v-if="loading" role="status">Loading homework…</p><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="!loading&&!error&&groups.overdue" class="overdue-hint">{{groups.overdue}} overdue assignment(s) still need attention. Open history to review them.</p><div class="homework-layout" :class="{'with-history':showHistory}"><div class="current-homework"><h3>Current assignments</h3><p v-if="!loading&&!error&&!groups.current.length">No current assignments. Past-due and reviewed work is available in history.</p><StudentHomeworkList :items="groups.current" :today="today" /></div><aside v-if="showHistory" :id="historyId" class="homework-history" aria-label="Homework history"><h3>Homework history</h3><p class="history-help">Past-due and reviewed work. Pending or missing work may still need attention.</p><p v-if="!loading&&!error&&!groups.history.length">No past-due or reviewed assignments.</p><StudentHomeworkList :items="groups.history" :today="today" /></aside></div></section></template>
<style scoped>
.homework-panel{min-width:0}.heading{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap}.heading h2{font-size:20px;margin:0}.homework-actions{display:flex;gap:8px;flex-wrap:wrap}.heading button{width:auto;margin:0;min-height:44px;padding:10px 12px;font-size:13px}.homework-layout{display:grid;grid-template-columns:minmax(0,1fr);gap:18px;margin-top:20px}.homework-layout.with-history{grid-template-columns:minmax(0,1fr) minmax(230px,280px);align-items:start}.current-homework,.homework-history{min-width:0}.homework-history{padding:16px;border:1px solid #dce6df;border-radius:12px;background:#f7faf8;position:sticky;top:0;max-height:65dvh;overflow:auto}.homework-layout h3{font-size:16px;margin:0 0 8px}.homework-layout>div>p,.history-help,.homework-history>p{font-size:13px;line-height:1.6;color:#62786b}.overdue-hint{margin:16px 0 0;padding:10px 12px;background:#fff5df;color:#7a602d;border-radius:8px;font-size:13px;line-height:1.5}.heading button:focus-visible{outline:2px solid #21896f;outline-offset:2px}@media(max-width:800px){.homework-layout.with-history{grid-template-columns:minmax(0,1fr)}.homework-history{position:static;max-height:none;overflow:visible}}@media(max-width:450px){.homework-actions{width:100%}.homework-actions button:first-child{flex:1}.heading h2{font-size:18px}}
</style>
